// Photoresistor — a light meter, both ways.
//
// The module has two outputs. AO is the LDR divider: more light, higher voltage
// (move the Light slider in the properties strip and watch the readings). DO is
// its comparator: high while light passes the threshold (the Threshold slider),
// so digitalRead() is the lamp that decides.
void setup() {
  Serial.begin(9600);
  pinMode(2, INPUT);
}

void loop() {
  Serial.print("light ");
  Serial.print(analogRead(A0));
  Serial.print("/1023  DO is ");
  Serial.println(digitalRead(2) == HIGH ? "on" : "off");
  delay(200);
}
